11	#include "runtime/rt_c_helpers.h"
12	#include <stdio.h>
13	
14	int main(void)
15	{
16	  printf("hello from QEMU1\n");
17	  fflush(stdout);
18	
19	  enter_vsim();
20	  /* Phase 2: vsim. No syscalls. */
21	  exit_vsim();
22	
23	  printf("hello from QEMU2\n");
24	  fflush(stdout);
